/**
 * The Marketplace's data layer: a comparison and a handoff in Peptaura's shape.
 *
 * Vendor-first: 42 researched vendors, ranked and GRADED the way the app's
 * vendor breakdown grades them (the reptides four-pillar score, the tier
 * letter, the independent COA score and its components, the price position
 * against the directory). Then a catalog of compounds, each with one row per
 * vendor that stocks it, ordered by that ranking.
 *
 * Data is generated by `scripts/build-shop-data.mjs` from the app repo's
 * vendor research and the live product pulls; never hand-edit the JSON. The
 * derivations below (effective score, pillars, COA components) are ports of
 * `VendorModels.swift` / `VendorBreakdownView.swift`, so a vendor reads the
 * same on both surfaces.
 */
import vendorsRaw from "./data/shop-vendors.json";
import offersRaw from "./data/shop-offers.json";
import compoundsRaw from "./data/shop-compounds.json";
import coasRaw from "./data/shop-coas.json";
import listingsRaw from "./data/shop-listings.json";
import { dashesToCommas } from "./library";
import { CATEGORIES } from "./guideVocab";

export type Tier = "S" | "A" | "B" | "C" | "D" | "F";
export const TIERS: readonly Tier[] = ["S", "A", "B", "C", "D", "F"];
export type Verification = "none" | "blue" | "gold";
/** The app's category ramps, which the pillar bars and the score ring wear. */
export type Ramp = "warm" | "cool" | "gold" | "green";
/** The app's signifier scale: green strong, amber caution, red weak, yellow neutral. */
export type Signal = "high" | "mild" | "low" | "neutral";

export interface Coa {
  vendorSlug: string;
  vendorName: string;
  productName: string | null;
  compoundSlug: string | null;
  batch: string | null;
  lab: string | null;
  method: string | null;
  purity: number | null;
  netContentMg: number | null;
  vialsTested: number | null;
  date: string | null;
  pdf: string | null;
}

export interface CoaExample {
  productName: string | null;
  batchNumber: string | null;
  labName: string | null;
  testMethod: string | null;
  purityPercent: number | null;
  netContentMg: number | null;
  vialsTested: number | null;
  testDate: string | null;
  endotoxin: string | null;
  heavyMetals: string | null;
  sterility: string | null;
  coaPdf: string | null;
}

export interface CoaComponent {
  label: string;
  weight: number | null;
  value: number;
}

export interface Cert {
  value: string;
  label: string;
}

export interface PillarScores {
  voice: number | null;
  age: number | null;
  scale: number | null;
  labs: number | null;
}

export interface ShopVendor {
  slug: string;
  name: string;
  domain: string | null;
  url: string | null;
  /** Discount code the vendor honours for REGEN readers, if any. */
  code: string | null;
  country: string | null;
  location: string | null;
  logoUrl: string | null;
  tagline: string | null;
  summary: string | null;
  differentiator: string | null;
  standoutPro: string | null;
  standoutCon: string | null;
  verdict: string | null;
  labs: string[] | null;
  testingScope: string[] | null;
  coaArchive: boolean | null;
  coaCount: number | null;
  coaAvgPurity: number | null;
  independentlyTested: boolean | null;
  contaminantTrifecta: boolean | null;
  legalEntity: string | null;
  founderNamed: boolean | null;
  strengthTags: string[] | null;
  watchoutTags: string[] | null;
  trustpilotCount: number | null;
  trustpilotAverage: number | null;
  skuCount: number | null;
  domainAgeMonths: number | null;
  researchStatus: string | null;
  verification: Verification | null;
  xHandle: string | null;
  /** Editorial tier, S to F, from the research pipeline. Null = unranked. */
  tier: Tier | null;
  /** Independent COA scorecard (disclosedlabs.com), 0-100, when indexed. */
  coaScore: number | null;
  coaGrade: string | null;
  /** 0 to 1, 1 = cheapest in the directory on a standard basket. */
  priceFraction: number | null;
  priceUsdPerMg: number | null;
  testedPeptideCount: number | null;
  contact: string | null;
  rank: number;
  /** The reptides four-pillar rubric, 0-10, where one was recorded. */
  score: number | null;
  scores: PillarScores | null;
  coaComponents: CoaComponent[];
  certs: Cert[];
  sources: { title: string | null; url: string }[];
  coaExamples: CoaExample[];
  incidents: { date?: string; text?: string; summary?: string; source?: string }[];
}

export interface Variant {
  label: string | null;
  sizeMg: number | null;
  /** Vials in the pack. Null when the store sells a multi-vial pack without
   *  saying how many; such a pack shows a price but no price per mg. */
  quantity: number | null;
  priceUsd: number;
  available: boolean | null;
}

/** "1 vial", "10 vials", or "Pack" when the count is not known. */
export function packLabel(v: Variant): string {
  if (v.quantity === null) return "Pack";
  return v.quantity > 1 ? `${v.quantity} vials` : "1 vial";
}

export interface Offer {
  compoundSlug: string;
  vendorSlug: string;
  productName: string;
  productUrl: string;
  currency: "USD" | "AUD";
  fetchedAt: string | null;
  variants: Variant[];
}

export interface ShopCompound {
  slug: string;
  name: string;
  kind: "compound" | "blend" | "essential";
  vendorCount: number;
  variantCount: number;
  sizesMg: number[];
  minUsdPerMg: number | null;
  /** Library guide slug when the compound has a page. */
  guideSlug: string | null;
  /** The library's body-system category, when the compound has a guide row. */
  category: string | null;
}

/* ---- Load (cleaned once) --------------------------------------------------- */

const clean = (s: string | null) => (s ? dashesToCommas(s) : s);

export const SHOP_VENDORS: ShopVendor[] = (vendorsRaw as unknown as ShopVendor[])
  .map((v) => ({
    ...v,
    tier: TIERS.includes(v.tier as Tier) ? v.tier : null,
    verification: (v.verification === "blue" || v.verification === "gold" ? v.verification : "none") as Verification,
    tagline: clean(v.tagline),
    summary: clean(v.summary),
    differentiator: clean(v.differentiator),
    standoutPro: clean(v.standoutPro),
    standoutCon: clean(v.standoutCon),
    verdict: clean(v.verdict),
    location: clean(v.location),
    testingScope: v.testingScope?.map((t) => dashesToCommas(t)) ?? null,
    incidents: (v.incidents ?? []).map((i) => ({ ...i, text: i.text ? dashesToCommas(i.text) : i.text })),
    sources: (v.sources ?? []).map((s) => ({ ...s, title: s.title ? dashesToCommas(s.title) : s.title })),
  }))
  // The order IS the score: highest score first, the research pipeline's
  // rank only breaking ties. Ranking by the pipeline's own order put an 8
  // below a 6.8 on the same page ("shows our inconsistency as a platform").
  // `rank` is rewritten to the position so every surface agrees.
  .sort((a, b) => effectiveScore(b) - effectiveScore(a) || a.rank - b.rank)
  .map((v, i) => ({ ...v, rank: i + 1 }));

export const SHOP_OFFERS: Offer[] = offersRaw as Offer[];
export const SHOP_COMPOUNDS: ShopCompound[] = compoundsRaw as ShopCompound[];
export const SHOP_COAS: Coa[] = (coasRaw as Coa[]).map((c) => ({ ...c, method: c.method ? dashesToCommas(c.method) : c.method }));

const VENDOR_BY_SLUG = new Map(SHOP_VENDORS.map((v) => [v.slug, v]));
const COMPOUND_BY_SLUG = new Map(SHOP_COMPOUNDS.map((c) => [c.slug, c]));
const OFFERS_BY_COMPOUND = new Map<string, Offer[]>();
for (const o of SHOP_OFFERS) {
  if (!OFFERS_BY_COMPOUND.has(o.compoundSlug)) OFFERS_BY_COMPOUND.set(o.compoundSlug, []);
  OFFERS_BY_COMPOUND.get(o.compoundSlug)!.push(o);
}
const OFFERS_BY_VENDOR = new Map<string, Offer[]>();
for (const o of SHOP_OFFERS) {
  if (!OFFERS_BY_VENDOR.has(o.vendorSlug)) OFFERS_BY_VENDOR.set(o.vendorSlug, []);
  OFFERS_BY_VENDOR.get(o.vendorSlug)!.push(o);
}

export function vendorBySlug(slug: string): ShopVendor | undefined {
  return VENDOR_BY_SLUG.get(slug);
}

export function compoundBySlug(slug: string): ShopCompound | undefined {
  return COMPOUND_BY_SLUG.get(slug);
}

export function shopHref(compoundSlug: string): string {
  return `/shop/${compoundSlug}`;
}

export function vendorHref(vendorSlug: string): string {
  return `/shop/vendors/${vendorSlug}`;
}

/** Vendors with a live catalog on the site. */
export function vendorsWithOffers(): ShopVendor[] {
  return SHOP_VENDORS.filter((v) => OFFERS_BY_VENDOR.has(v.slug));
}

/* ---- Grading (ports of VendorModels.swift) ----------------------------------- */

export interface Pillar {
  key: "voice" | "age" | "scale" | "labs";
  label: string;
  value: number;
  ramp: Ramp;
}

const PILLAR_RAMP: Record<Pillar["key"], Ramp> = { voice: "warm", age: "cool", scale: "gold", labs: "green" };

/** reptides' four axes computed from what the research holds, 0-10 each, so
 *  a vendor the rubric never scored still reads on the same scale. */
export function derivedPillars(v: ShopVendor): Record<Pillar["key"], number> {
  let voice = 0;
  if (v.trustpilotAverage !== null && v.trustpilotCount) {
    const rating = Math.min(10, Math.max(0, ((v.trustpilotAverage - 2) / 3) * 10));
    const volume = Math.min(1, Math.log10(v.trustpilotCount + 1) / 2.3);
    voice = Math.round(rating * (0.55 + 0.45 * volume));
  }
  const age = v.domainAgeMonths ? Math.min(10, Math.round((v.domainAgeMonths / 36) * 10)) : 0;
  const scale = v.skuCount ? Math.min(10, Math.round((v.skuCount / 60) * 10)) : 0;
  let labs = 0;
  if (v.coaArchive) labs += 2;
  if (v.coaExamples.length) labs += 2;
  if (v.coaExamples.some((c) => c.labName)) labs += 2;
  else if (v.labs?.length) labs += 1;
  if (v.contaminantTrifecta) labs += 2;
  if (v.independentlyTested) labs += 2;
  return { voice, age, scale, labs: Math.min(10, labs) };
}

/** The four pillars, always four: the recorded rubric when it exists, else the derived read. */
export function pillarsFor(v: ShopVendor): Pillar[] {
  const s = v.scores;
  const src: Record<Pillar["key"], number> =
    s && s.voice !== null && s.age !== null && s.scale !== null && s.labs !== null
      ? { voice: s.voice, age: s.age, scale: s.scale, labs: s.labs }
      : derivedPillars(v);
  return (["voice", "age", "scale", "labs"] as const).map((key) => ({ key, label: key, value: src[key], ramp: PILLAR_RAMP[key] }));
}

/** The recorded 0-10 score, or the mean of the derived pillars. Every vendor has one. */
export function effectiveScore(v: ShopVendor): number {
  if (v.score !== null) return v.score;
  const d = derivedPillars(v);
  return (d.voice + d.age + d.scale + d.labs) / 4;
}

export function formatScore(n: number): string {
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

/** Ring and band colour for a 0-10 score: green strong, gold middle, warm weak. */
export function scoreRamp(score: number): Ramp {
  if (score >= 7) return "green";
  if (score >= 4) return "gold";
  return "warm";
}

export function scoreBand(score: number): string {
  if (score >= 8) return "Excellent";
  if (score >= 7) return "Strong";
  if (score >= 5.5) return "Good";
  if (score >= 4) return "Average";
  return "Weak";
}

export const SCORE_BLURB = "Weighted across customer voice, operating age, catalog scale, and independent lab verification.";

/** Where the vendor's basket price sits against the directory. */
export function priceStatus(fraction: number): { word: string; signal: Signal } {
  if (fraction >= 0.62) return { word: "Priced well", signal: "high" };
  if (fraction >= 0.42) return { word: "At market", signal: "mild" };
  return { word: "Priced high", signal: "low" };
}

/** The app's COA grade bands (CoaCard.swift): harsher than the tier scale. */
export function coaTier(score: number | null): Tier | null {
  if (score === null) return null;
  if (score >= 92) return "S";
  if (score >= 80) return "A";
  if (score >= 68) return "B";
  if (score >= 54) return "C";
  if (score >= 38) return "D";
  return "F";
}

export interface CoaPillar {
  label: string;
  value: number;
  ramp: Ramp;
}

function shortComponentLabel(label: string): string {
  const l = label.toLowerCase();
  if (l.includes("purity")) return "purity";
  if (l.includes("panel") || l.includes("safety")) return "panels";
  if (l.includes("corrobor") || l.includes("lab")) return "lab match";
  if (l.includes("forgery")) return "forgery";
  if (l.includes("archive") || l.includes("coverage")) return "archive";
  return label.split(" ")[0] ?? label;
}

/** The four components behind the independent grade, or the same four axes
 *  derived from the certificates the research holds, on one 0-100 scale. */
export function coaPillarsFor(v: ShopVendor): CoaPillar[] {
  const ramps: Ramp[] = ["warm", "cool", "gold", "green"];
  let components: { label: string; value: number }[];
  if (v.coaComponents.length) {
    components = v.coaComponents.map((c) => ({ label: c.label, value: c.value }));
  } else {
    const ex = v.coaExamples;
    const purities = ex.map((c) => c.purityPercent).filter((p): p is number => p !== null);
    const purity = purities.length ? Math.floor(purities.reduce((a, b) => a + b, 0) / purities.length) : 0;
    const covered = ex.reduce((n, c) => n + (c.endotoxin ? 1 : 0) + (c.heavyMetals ? 1 : 0) + (c.sterility ? 1 : 0), 0);
    const panel = ex.length ? Math.round((covered / (ex.length * 3)) * 100) : 0;
    const labMatch = ex.some((c) => c.labName) ? 90 : v.labs?.length ? 60 : 0;
    let archive = 0;
    if (v.coaArchive) {
      if (v.testedPeptideCount && v.skuCount) archive = Math.min(100, Math.round((v.testedPeptideCount / v.skuCount) * 100));
      else archive = ex.length ? 50 : 0;
    }
    components = [
      { label: "Avg Purity", value: purity },
      { label: "Safety Panel Coverage", value: panel },
      { label: "Lab Corroboration", value: labMatch },
      { label: "Archive Coverage", value: archive },
    ];
  }
  return components.map((c, i) => ({ label: shortComponentLabel(c.label), value: c.value, ramp: ramps[i % ramps.length] }));
}

export interface CoaAnalysis {
  title: string;
  score: number | null;
  /** The grade word beside the status dot: "A Tier", "None published". */
  grade: string;
  tier: Tier | null;
  body: string;
}

const SEVEN_PANELS = (c: CoaExample): number =>
  [c.purityPercent !== null, /ident|ms|mass/i.test(c.testMethod ?? ""), c.netContentMg !== null, Boolean(c.vialsTested), Boolean(c.endotoxin), Boolean(c.heavyMetals), Boolean(c.sterility)].filter(
    Boolean
  ).length;

/** What the COA section leads with: the independent grade, a completeness
 *  read of the lead certificate, or the plain fact that none is published. */
export function coaAnalysisFor(v: ShopVendor): CoaAnalysis {
  if (v.coaScore !== null) {
    const tier = v.coaGrade && TIERS.includes(v.coaGrade as Tier) ? (v.coaGrade as Tier) : coaTier(v.coaScore);
    const source = `Graded by Disclosed Labs from ${v.coaCount ? `${v.coaCount} ` : ""}certificates published by the testing labs themselves`;
    const purity = v.coaAvgPurity !== null ? `, averaging ${v.coaAvgPurity.toFixed(2)}% HPLC purity` : "";
    const weakest = v.coaComponents.length ? v.coaComponents.reduce((a, b) => (b.value < a.value ? b : a)) : null;
    const body = weakest
      ? `${source}${purity}. The component holding the grade down is ${weakest.label.toLowerCase()} at ${weakest.value}${weakest.weight ? `, carrying ${weakest.weight}% of the weight` : ""}.`
      : `${source}${purity}.`;
    return { title: "Independent COA grade", score: v.coaScore, grade: tier ? `${tier} Tier` : String(v.coaScore), tier, body };
  }
  const lead = v.coaExamples[0];
  if (lead) {
    const present = SEVEN_PANELS(lead);
    const score = Math.round((present / 7) * 100);
    const missing = 7 - present;
    const base = "This is a completeness read of the certificate itself, what it documents, not how the compound performed.";
    const body =
      missing === 0
        ? `${base} Every panel we check for is present on this one.`
        : `${base} ${missing} of the seven panels we check for ${missing === 1 ? "is" : "are"} absent, and no independent grader has scored this vendor's archive.`;
    const tier = coaTier(score);
    return { title: "What this certificate covers", score, grade: `${tier} Tier`, tier, body };
  }
  let body = `${v.name} publishes no per-batch certificates that can be browsed before ordering`;
  if (v.coaArchive === false) body += ", certificates ship per order or arrive on request, so purity claims cannot be checked in advance";
  body += ".";
  if (v.labs?.length) body += ` Testing is described as running through ${v.labs.slice(0, 2).join(" and ")}, but no certificate is published to confirm it.`;
  else body += " No independent test results exist either, so every purity number on the storefront is the vendor's own word.";
  return { title: "Certificate record", score: null, grade: "None published", tier: null, body };
}

/** Up to six hard numbers: the research's cert facts when written, else read off the data. */
export function proofFacts(v: ShopVendor): Cert[] {
  if (v.certs.length) return v.certs.slice(0, 6);
  const facts: Cert[] = [];
  const lead = v.coaExamples[0];
  if (lead?.purityPercent !== null && lead?.purityPercent !== undefined) facts.push({ label: "HPLC Purity", value: `${lead.purityPercent.toFixed(2)}%` });
  if (lead?.netContentMg) facts.push({ label: "Net Content", value: `${lead.netContentMg.toFixed(1)} mg` });
  if (v.coaCount) facts.push({ label: "Published COAs", value: String(v.coaCount) });
  if (v.coaAvgPurity !== null) facts.push({ label: "Archive Avg Purity", value: `${v.coaAvgPurity.toFixed(2)}%` });
  if (v.trustpilotAverage !== null) facts.push({ label: "Trustpilot", value: `${v.trustpilotAverage.toFixed(1)} · ${v.trustpilotCount ?? 0} reviews` });
  if (v.skuCount) facts.push({ label: "Catalog SKUs", value: String(v.skuCount) });
  if (v.domainAgeMonths) facts.push({ label: "Storefront Age", value: `${v.domainAgeMonths} months` });
  return facts.slice(0, 6);
}

export function verificationLabel(v: ShopVendor): string | null {
  if (v.verification === "gold") return "REGEN Partner";
  if (v.verification === "blue") return "REGEN Vetted";
  return null;
}

/** The year the storefront went up, from the domain's age. Null when unknown. */
export function foundedYear(v: ShopVendor): number | null {
  if (!v.domainAgeMonths) return null;
  const d = new Date();
  d.setMonth(d.getMonth() - v.domainAgeMonths);
  return d.getFullYear();
}

/**
 * The quiet facts under a vendor's name: what is on record, as words on one
 * line. The pill tag cloud this replaced read as clutter; the facts are the
 * same record, said once each.
 */
export function vendorFacts(v: ShopVendor, max = 3): string[] {
  const f: string[] = [];
  if (v.independentlyTested) f.push("Third-party tested");
  if (v.coaArchive) f.push(v.coaCount ? `${v.coaCount} public COAs` : "Public COAs");
  if (v.labs?.length) f.push(`${v.labs.length} named lab${v.labs.length === 1 ? "" : "s"}`);
  if (v.legalEntity || v.founderNamed) f.push("Named operator");
  if (v.country) f.push(v.country);
  return f.slice(0, max);
}

export interface VendorStat {
  label: string;
  value: string;
  /** Set when the value stands in for a missing record. */
  none?: boolean;
}

/** The numbers beside a vendor on the podium and in the directory:
 *  certificates, reviews, labs. Missing records are said to be missing. */
export function vendorStats(v: ShopVendor): VendorStat[] {
  const coas: VendorStat = v.coaCount
    ? { label: "Public COAs", value: String(v.coaCount) }
    : v.coaArchive
      ? { label: "Public COAs", value: "Archive" }
      : { label: "Public COAs", value: "None", none: true };
  const reviews: VendorStat =
    v.trustpilotAverage !== null
      ? { label: v.trustpilotCount ? `${v.trustpilotCount} reviews` : "Trustpilot", value: v.trustpilotAverage.toFixed(1) }
      : { label: "Trustpilot", value: "None", none: true };
  const labs: VendorStat = v.labs?.length
    ? { label: `Named lab${v.labs.length === 1 ? "" : "s"}`, value: String(v.labs.length) }
    : { label: "Named labs", value: "None", none: true };
  return [coas, reviews, labs];
}

/* ---- Offer rows -------------------------------------------------------------- */

export interface OfferRow {
  vendorSlug: string;
  vendorName: string;
  logoUrl: string | null;
  rank: number;
  tier: Tier | null;
  score: number;
  verification: Verification | null;
  country: string | null;
  code: string | null;
  independentlyTested: boolean;
  coaArchive: boolean;
  coaCount: number | null;
  trustpilotAverage: number | null;
  labs: string[];
  purity: number | null;
  productName: string;
  productUrl: string;
  currency: "USD" | "AUD";
  variants: Variant[];
  latestCoa: { date: string | null; pdf: string | null; lab: string | null; batch: string | null } | null;
}

const norm = (s: string) => s.toLowerCase().replace(/\(.*?\)/g, "").replace(/[^a-z0-9]+/g, " ").trim();

/** The vendor's most recent COA whose product name names this compound. */
export function latestCoaFor(vendor: ShopVendor, compoundName: string): OfferRow["latestCoa"] {
  const key = norm(compoundName).split(" ")[0];
  if (!key) return null;
  const hits = vendor.coaExamples
    .filter((c) => c.productName && norm(c.productName).includes(key))
    .sort((a, b) => String(b.testDate ?? "").localeCompare(String(a.testDate ?? "")));
  const c = hits[0];
  return c ? { date: c.testDate, pdf: c.coaPdf, lab: c.labName, batch: c.batchNumber } : null;
}

/**
 * One row per VENDOR for the compound, in Recommended order. A vendor that
 * lists the compound as several products (sizes, pack counts) gets one row
 * with every pack inside it; a row per product put the same vendor on the
 * page three times.
 */
export function offerRowsFor(compound: ShopCompound): OfferRow[] {
  const list = OFFERS_BY_COMPOUND.get(compound.slug) ?? [];
  const byVendor = new Map<string, OfferRow>();
  for (const o of list) {
    const v = VENDOR_BY_SLUG.get(o.vendorSlug);
    if (!v) continue;
    let row = byVendor.get(v.slug);
    if (!row) {
      row = {
        vendorSlug: v.slug,
        vendorName: v.name,
        logoUrl: v.logoUrl,
        rank: v.rank,
        tier: v.tier,
        score: effectiveScore(v),
        verification: v.verification,
        country: v.country,
        code: v.code,
        independentlyTested: Boolean(v.independentlyTested),
        coaArchive: Boolean(v.coaArchive),
        coaCount: v.coaCount,
        trustpilotAverage: v.trustpilotAverage,
        labs: v.labs ?? [],
        purity: v.coaAvgPurity,
        productName: o.productName,
        productUrl: o.productUrl,
        currency: o.currency,
        variants: [],
        latestCoa: latestCoaFor(v, compound.name),
      };
      byVendor.set(v.slug, row);
    }
    for (const x of o.variants) {
      const dup = row.variants.some((y) => y.sizeMg === x.sizeMg && y.quantity === x.quantity && y.priceUsd === x.priceUsd);
      if (!dup) row.variants.push({ ...x, label: x.label ?? o.productName });
    }
  }
  for (const row of byVendor.values()) {
    row.variants.sort(
      (a, b) => (a.sizeMg ?? 0) - (b.sizeMg ?? 0) || (a.quantity ?? 99) - (b.quantity ?? 99) || a.priceUsd - b.priceUsd
    );
  }
  return [...byVendor.values()].sort((a, b) => a.rank - b.rank || a.vendorName.localeCompare(b.vendorName));
}

/** Price per mg for a variant, or null when the size is unknown. */
export function perMg(v: Variant): number | null {
  if (!v.sizeMg || !v.quantity) return null;
  return v.priceUsd / (v.sizeMg * v.quantity);
}

export function money(n: number, currency: "USD" | "AUD" = "USD"): string {
  const s = n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return currency === "AUD" ? `A$${s}` : `$${s}`;
}

export function mg(n: number): string {
  return `${Number.isInteger(n) ? n : n.toFixed(1)} mg`;
}

export interface VendorCatalogRow {
  compound: ShopCompound;
  offers: Offer[];
  /** Every distinct pack across the vendor's products for this compound, cheapest per mg first. */
  packs: { variant: Variant; offer: Offer; perMg: number | null }[];
  bestPerMg: number | null;
}

/** Offers grouped by compound for a vendor's catalog, with the packs flattened. */
export function vendorCatalog(vendor: ShopVendor): VendorCatalogRow[] {
  const list = OFFERS_BY_VENDOR.get(vendor.slug) ?? [];
  const groups = new Map<string, Offer[]>();
  for (const o of list) {
    if (!groups.has(o.compoundSlug)) groups.set(o.compoundSlug, []);
    groups.get(o.compoundSlug)!.push(o);
  }
  return [...groups.entries()]
    .map(([slug, offers]) => {
      const packs: VendorCatalogRow["packs"] = [];
      for (const offer of offers) {
        for (const variant of offer.variants) {
          const dup = packs.some((p) => p.variant.sizeMg === variant.sizeMg && p.variant.quantity === variant.quantity && p.variant.priceUsd === variant.priceUsd);
          if (!dup) packs.push({ variant, offer, perMg: offer.currency === "USD" ? perMg(variant) : null });
        }
      }
      packs.sort((a, b) => (a.perMg ?? Infinity) - (b.perMg ?? Infinity) || a.variant.priceUsd - b.variant.priceUsd);
      const best = packs.find((p) => p.perMg !== null)?.perMg ?? null;
      return { compound: COMPOUND_BY_SLUG.get(slug)!, offers, packs, bestPerMg: best };
    })
    .filter((g) => g.compound)
    .sort((a, b) => a.compound.name.localeCompare(b.compound.name));
}

export interface StoreListing {
  name: string;
  fromUsd: number;
  url: string;
  compoundSlug: string | null;
}

const LISTINGS = listingsRaw as Record<string, { source: string; fetchedAt: string; items: StoreListing[] }>;

/**
 * What a vendor's Catalog tab can honestly show, best source first:
 * "live"     its catalog was read (packs, sizes, per mg);
 * "listing"  the store's own published product list (name, starting price, link);
 * "coas"     the compounds it publishes certificates for (no prices);
 * "none"     nothing on file, and the tab is not drawn.
 */
export type StoreCatalog =
  | { kind: "live"; rows: VendorCatalogRow[] }
  | { kind: "listing"; source: string; fetchedAt: string; items: StoreListing[] }
  | { kind: "coas"; items: { name: string; compoundSlug: string | null; count: number }[] }
  | { kind: "none" };

export function storeCatalogFor(v: ShopVendor): StoreCatalog {
  const rows = vendorCatalog(v);
  if (rows.length) return { kind: "live", rows };
  const l = LISTINGS[v.slug];
  if (l?.items.length) return { kind: "listing", source: l.source, fetchedAt: l.fetchedAt, items: l.items };
  const tally = new Map<string, { name: string; compoundSlug: string | null; count: number }>();
  for (const c of v.coaExamples) {
    const raw = (c.productName ?? "").replace(/\s*\d+(\.\d+)?\s*mg.*$/i, "").trim();
    if (!raw || /[/+]/.test(raw)) continue;
    const slug = SHOP_COMPOUNDS.find((x) => norm(x.name) === norm(raw))?.slug ?? null;
    const key = slug ?? norm(raw);
    const hit = tally.get(key);
    if (hit) hit.count += 1;
    else tally.set(key, { name: slug ? COMPOUND_BY_SLUG.get(slug)!.name : raw, compoundSlug: slug, count: 1 });
  }
  if (tally.size) return { kind: "coas", items: [...tally.values()].sort((a, b) => a.name.localeCompare(b.name)) };
  return { kind: "none" };
}

export function storeCatalogCount(c: StoreCatalog): number {
  return c.kind === "live" ? c.rows.length : c.kind === "none" ? 0 : c.items.length;
}

/** The one-line trust statement under a vendor's name. */
export function trustLine(v: ShopVendor): string {
  const parts: string[] = [];
  if (v.independentlyTested && v.labs?.length) parts.push(`Third-party tested by ${v.labs.slice(0, 2).join(" and ")}`);
  else if (v.independentlyTested) parts.push("Third-party tested");
  if (v.coaArchive && v.coaCount) parts.push(`${v.coaCount} public COAs`);
  else if (v.coaArchive) parts.push("Public COA archive");
  if (v.country) parts.push(`Ships from ${v.country === "United States" ? "the US" : v.country}`);
  return parts.join(" · ");
}

/* ---- Catalog ------------------------------------------------------------------ */

export function topCompounds(n: number): ShopCompound[] {
  return SHOP_COMPOUNDS.filter((c) => c.kind === "compound").slice(0, n);
}

export interface CatalogSection {
  key: string;
  label: string;
  blurb: string | null;
  items: ShopCompound[];
}

/**
 * The catalog in the library's order: one section per body system, in the
 * library's own sequence, then the compounds with no guide row, blends with
 * two or more vendors, and the essentials. Items are most-stocked first.
 */
export function catalogSections(): CatalogSection[] {
  const byCount = (a: ShopCompound, b: ShopCompound) => b.vendorCount - a.vendorCount || a.name.localeCompare(b.name);
  const compounds = SHOP_COMPOUNDS.filter((c) => c.kind === "compound");
  const out: CatalogSection[] = [];
  for (const cat of CATEGORIES) {
    const items = compounds.filter((c) => c.category === cat.slug).sort(byCount);
    if (items.length) out.push({ key: cat.slug, label: cat.label, blurb: cat.blurb, items });
  }
  const other = compounds.filter((c) => !CATEGORIES.some((cat) => cat.slug === c.category)).sort(byCount);
  if (other.length) out.push({ key: "other", label: "Other compounds", blurb: "Stocked by vendors but not yet in the library.", items: other });
  const blends = SHOP_COMPOUNDS.filter((c) => c.kind === "blend" && c.vendorCount >= 2).sort(byCount);
  if (blends.length) out.push({ key: "blends", label: "Blends", blurb: "Two or more compounds in one vial, listed when two or more vendors stock them.", items: blends });
  const essentials = SHOP_COMPOUNDS.filter((c) => c.kind === "essential").sort(byCount);
  if (essentials.length) out.push({ key: "essentials", label: "Essentials", blurb: "Bacteriostatic water and syringes.", items: essentials });
  return out;
}

export function compoundCount(): number {
  return SHOP_COMPOUNDS.filter((c) => c.kind === "compound").length;
}

const COA_COUNT_BY_COMPOUND = new Map<string, number>();
for (const c of SHOP_COAS) if (c.compoundSlug) COA_COUNT_BY_COMPOUND.set(c.compoundSlug, (COA_COUNT_BY_COMPOUND.get(c.compoundSlug) ?? 0) + 1);

/** Certificates on file that name this compound, across every vendor. */
export function compoundCoaCount(slug: string): number {
  return COA_COUNT_BY_COMPOUND.get(slug) ?? 0;
}

export interface ShopSearchRow {
  slug: string;
  name: string;
  blurb: string;
  category: string;
  status: string;
  href: string;
}

/** The nav search on shop pages finds a compound or a vendor by name. */
export function shopSearchRows(): ShopSearchRow[] {
  return [
    ...SHOP_COMPOUNDS.map((c) => ({
      slug: c.slug,
      name: c.name,
      blurb: c.kind === "blend" ? "Blend" : c.kind === "essential" ? "Essential" : "",
      category: `${c.vendorCount} vendor${c.vendorCount === 1 ? "" : "s"}`,
      status: c.kind,
      href: shopHref(c.slug),
    })),
    ...SHOP_VENDORS.map((v) => ({
      slug: `vendor-${v.slug}`,
      name: v.name,
      blurb: v.tagline ?? trustLine(v),
      category: v.tier ? `Vendor · ${v.tier}-Tier` : "Vendor",
      status: "vendor",
      href: vendorHref(v.slug),
    })),
  ];
}

/* ---- The four buyer questions ---------------------------------------------- */

export interface Answer {
  /** The question, as a reader asks it. */
  q: string;
  /** The answer, in words. */
  a: string;
  /** Set when the answer says the record is missing. */
  none?: boolean;
}

/** Price against the market, in a buyer's words. */
export function priceWord(fraction: number | null): { a: string; none?: boolean } {
  if (fraction === null) return { a: "Prices not readable", none: true };
  if (fraction >= 0.62) return { a: "Cheaper than most" };
  if (fraction >= 0.42) return { a: "About average" };
  return { a: "Pricier than most" };
}

/**
 * What an ordinary buyer asks about a vendor, answered in words (2026-11-10,
 * "doesn't actually show the user information the average person would
 * find valuable about a vendor"): is it tested, who runs it, what do people
 * say, what does it cost. Each answer is one short line; a missing record
 * says so.
 */
export function vendorAnswers(v: ShopVendor, short = false): Answer[] {
  const tested: Answer = v.independentlyTested || v.coaArchive || v.coaExamples.length
    ? {
        q: "Is it tested?",
        a: [
          v.independentlyTested ? "Third-party tested" : "Tests published",
          v.coaCount ? `${v.coaCount} ${short ? "COAs" : "public COAs"}` : v.coaArchive ? (short ? "COA archive" : "public COA archive") : null,
          short ? null : v.labs?.length ? `${v.labs.length} named lab${v.labs.length === 1 ? "" : "s"}` : null,
        ]
          .filter(Boolean)
          .join(", "),
      }
    : { q: "Is it tested?", a: "No public testing", none: true };
  const who = v.legalEntity ? "Named company" : v.founderNamed ? "Named founder" : null;
  const year = foundedYear(v);
  const runsParts = short ? [v.country ?? null, year ? `since ${year}` : null].filter(Boolean) : [who, v.country ? (who ? `in ${v.country}` : v.country) : null, year ? `since ${year}` : null].filter(Boolean);
  const runs: Answer = runsParts.length ? { q: "Who runs it?", a: runsParts.join(", ") } : { q: "Who runs it?", a: "Operator not disclosed", none: true };
  const say: Answer =
    v.trustpilotAverage !== null && v.trustpilotCount
      ? { q: "What do people say?", a: short ? `${v.trustpilotAverage.toFixed(1)} on Trustpilot, ${v.trustpilotCount} reviews` : `${v.trustpilotAverage.toFixed(1)} of 5 on Trustpilot, ${v.trustpilotCount} review${v.trustpilotCount === 1 ? "" : "s"}` }
      : { q: "What do people say?", a: "No reviews on record", none: true };
  const cost: Answer = { q: "What does it cost?", ...priceWord(v.priceFraction) };
  return [tested, runs, say, cost];
}
